function onChange(control, oldValue, newValue, isLoading, isTemplate) {
   if (isLoading || newValue === '') {
      return;
   }
	alert("Attention on va copier la valeur du champ short_desc dans le champ description!!!");	
   //Type appropriate comment here, and begin script below
      //Type appropriate comment here, and begin script below
   var shortDesc = g_form.getValue("short_description"); // getValue permet de récupérer la valeur d'un champ et on vient de récupérer la valeur du champ short_description  shortDesc

g_form.setValue("description",shortDesc); // setValue permet de modifier la valeur d'un champ pour mettre la valeur qu'on a récupérer dans la variable shortDesc
}
